  function shape(kind, r) {
    var cx = 48, cy = 62, d = '', i, n, a, rr;
    if (kind === 'hex') {
      for (i = 0; i < 6; i++) { a = (-90 + i * 60) * Math.PI / 180; d += (i ? 'L' : 'M') + (cx + r * 1.04 * Math.cos(a)).toFixed(1) + ' ' + (cy + r * 1.04 * Math.sin(a)).toFixed(1); }
      return d + 'Z';
    }
    if (kind === 'octa') {
      for (i = 0; i < 8; i++) { a = (-90 + 22.5 + i * 45) * Math.PI / 180; d += (i ? 'L' : 'M') + (cx + r * 1.03 * Math.cos(a)).toFixed(1) + ' ' + (cy + r * 1.03 * Math.sin(a)).toFixed(1); }
      return d + 'Z';
    }
    if (kind === 'seal') {
      n = 32;
      for (i = 0; i < n; i++) { a = (-90 + i * 360 / n) * Math.PI / 180; rr = i % 2 ? r - 2.4 : r + .6; d += (i ? 'L' : 'M') + (cx + rr * Math.cos(a)).toFixed(1) + ' ' + (cy + rr * Math.sin(a)).toFixed(1); }
      return d + 'Z';
    }
    return 'M' + (cx - r) + ' ' + cy + 'a' + r + ' ' + r + ' 0 1 0 ' + (2 * r) + ' 0a' + r + ' ' + r + ' 0 1 0 ' + (-2 * r) + ' 0Z';
  }
  // inner rings stay circular on the scalloped seal, so the stamped face stays clean
  function ring(kind, r) { return shape(kind === 'seal' ? 'round' : kind, r); }
  function pt(a, r) { return [48 + r * Math.cos(a), 62 + r * Math.sin(a)]; }
  function gemPts(kind) {
    var o = [], i, a;
    if (kind === 'hex') for (i = 0; i < 6; i++) { a = (-90 + i * 60) * Math.PI / 180; o.push(pt(a, 36.4)); }
    else if (kind === 'seal') for (i = 0; i < 8; i++) { a = (-90 + i * 45) * Math.PI / 180; o.push(pt(a, 34.6)); }
    else for (i = 0; i < 12; i++) { a = (-90 + i * 30) * Math.PI / 180; o.push(pt(a, 34.8)); }
    return o;
  }
